      SUBROUTINE BEAM2CC     SECOND-ORDER CONTRIBUTIONS TO BEAM MATRIXCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TR.CIN'      INCLUDE 'TS.CIN'CC     LOCAL VARIABLESCCC--------------------------------------------------------------------C     CENTROID ADJUSTMENT DUE TO SECOND-ORDER TERMS ACTING ONC     BEAM WIDTHC      DO 20 J = 1, 5      SS = 0.0      IND = 0      DO 10 L2 = 1, 6      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + TC2(J,IND)*SI(L1,L2)   10 CONTINUE      CEN(J) = CEN(J) + SS   20 CONTINUECC     SECOND-ORDER CONTRIBUTION TO BEAM SIZEC      DO 40 J = 1, 5      DO 40 L1 = 1, 6      INDA = 0      DO 40 K = 1, 6      SS = 0.0      DO 30 L2 = 1, K      INDA = INDA + 1      SS = SS + TC2(J,INDA)*SI(L1,L2)   30 CONTINUE      TR(J,L1,K) = SS   40 CONTINUEC      DO 60 J = 1, 5      INDA = 0      DO 60 L1 = 1, 6      DO 60 K = 1, L1      INDA = INDA + 1      SS = 0.0      DO 50 L2 = 1, 6      SS = SS + TR(J,K,L2)*SI(L1,L2)   50 CONTINUE      TS(J,INDA) = SS   60 CONTINUEC      DO 80 J = 1, 5      DO 80 K = 1, J      TSST = 0.0      DO 70 L1 = 1, 6      DO 70 L2 = 1, 6      TSST = TSST + TR(J,L1,L2)*TR(K,L2,L1)   70 CONTINUE      SIT(J,K) = SIT(J,K) + TSST   80 CONTINUEC      DO 100 J = 1, 5      DO 100 K = 1, J      TSST = 0.0      DO 90 IND = 1, 21      TSST = TSST + TS(J,IND)*TC2(K,IND)   90 CONTINUE      SIT(J,K) = SIT(J,K) + TSST  100 CONTINUEC      RETURN      END